CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
ALTER TABLE products
  ADD COLUMN name_norm text
  GENERATED ALWAYS AS (lower(immutable_unaccent(name))) STORED;
CREATE INDEX products_name_trgm ON products USING gin (name_norm gin_trgm_ops);

CREATE TABLE audit_logs (
  id          bigserial PRIMARY KEY,
  actor_id    uuid,          -- ai; null nếu là job hệ thống
  actor_type  text,          -- user | admin | system
  action      text NOT NULL, -- order.update, order.refund
  entity_type text NOT NULL,
  entity_id   text NOT NULL,
  changes     jsonb,         -- { field: { from, to } }
  request_id  text,
  ip          inet,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON audit_logs (entity_type, entity_id, created_at DESC);

